"""w8 E6: Prop B. The lattice generated by the level partitions of two complete b-ary trees:
is it a poset block structure (uniform, commuting, distributive)? Coordinate tanglegrams vs
twisted ones (leaf transpositions, random bijections)."""
import itertools, random, sys
import os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from w8lib import poset_2dim, best_order

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1)


def canon(p):
    m, out = {}, []
    for c in p:
        if c not in m: m[c] = len(m)
        out.append(m[c])
    return tuple(out)


def meet(p, q):
    return canon(tuple(zip(p, q)))


def join(p, q):
    n = len(p)
    par = list(range(n))
    def f(v):
        while par[v] != v:
            par[v] = par[par[v]]; v = par[v]
        return v
    for part in (p, q):
        first = {}
        for i, c in enumerate(part):
            if c in first: par[f(i)] = f(first[c])
            else: first[c] = i
    return canon(tuple(f(i) for i in range(n)))


def finer_eq(p, q):    # p refines q
    return join(p, q) == q


def closure(gens, limit):
    S = set(gens)
    frontier = list(S)
    while frontier:
        new = []
        cur = list(S)
        for p in frontier:
            for q in cur:
                for r in (meet(p, q), join(p, q)):
                    if r not in S:
                        S.add(r); new.append(r)
                        if len(S) > limit:
                            return S, False
        frontier = new
    return S, True


def uniform(p):
    from collections import Counter
    return len(set(Counter(p).values())) == 1


def commute(p, q):
    """R_p R_q == R_q R_p  <=>  for uniform partitions: |join class| * |meet class| == |p class| * |q class|"""
    from collections import Counter
    cp, cq, cm, cj = Counter(p), Counter(q), Counter(meet(p, q)), Counter(join(p, q))
    m = meet(p, q); j = join(p, q)
    return all(cj[j[x]] * cm[m[x]] == cp[p[x]] * cq[q[x]] for x in range(len(p)))


def is_pbs(S):
    S = list(S)
    if not all(uniform(p) for p in S):
        return "non-uniform"
    for p, q in itertools.combinations(S, 2):
        if not commute(p, q):
            return "non-commuting"
    for p, q, r in itertools.product(S, repeat=3):
        if meet(p, join(q, r)) != join(meet(p, q), meet(p, r)):
            return "non-distributive"
    return "PBS"


def jirr_count(S):
    """number of join-irreducible elements (excluding the bottom = discrete partition):
    elements with exactly one lower cover in S"""
    S = list(S)
    count = 0
    for p in S:
        below = [q for q in S if q != p and finer_eq(q, p)]
        if not below:
            continue
        covers = [q for q in below if not any(r != q and finer_eq(q, r) and r in below for r in below)]
        if len(covers) == 1:
            count += 1
    return count


def levels(b, h, order, leafmap=None):
    pts = list(itertools.product(range(b), repeat=h))
    out = []
    for k in range(h + 1):
        out.append(canon(tuple(tuple((leafmap[z] if leafmap else z)[order[i]] for i in range(k)) for z in pts)))
    return out


for b, h in [(2, 4), (2, 5), (3, 3), (2, 6)]:
    pts = list(itertools.product(range(b), repeat=h))
    for trial in range(3):
        rho = list(range(h)); rng.shuffle(rho)
        for kind in ['coord', 'swap1', 'random']:
            mp = {z: z for z in pts}
            if kind == 'swap1':
                a, c = rng.sample(pts, 2); mp[a], mp[c] = mp[c], mp[a]
            elif kind == 'random':
                perm = pts[:]; rng.shuffle(perm); mp = dict(zip(pts, perm))
            gens = levels(b, h, list(range(h))) + levels(b, h, rho, mp)
            S, ok = closure(gens, len(pts) + 2)
            verdict = is_pbs(S) if ok else "closure>|L|+1"
            extra = ""
            if verdict == "PBS":
                pred = poset_2dim(list(range(h)), rho)
                down = set()
                # number of down-sets of P_{id,rho}
                nd = sum(1 for mask in range(1 << h)
                         if all(all((mask >> j) & 1 for j in pred[i]) for i in range(h) if (mask >> i) & 1))
                extra = f"|L(T,T')|={len(S)} #downsets(P)={nd} JI={jirr_count(S)} mu(P)={best_order(pred)[0]}"
            print(f"E6 b={b} h={h} rho={rho} {kind:6s}: closure size {len(S):4d}  {verdict:17s} {extra}", flush=True)
